cd /tmp && cat > extract.js <<'EOF'
const fs=require("fs");
const file=process.argv[2];
let h=fs.readFileSync(file,"utf8");
// remove script/style/nav/footer/svg blocks
h=h.replace(/<script[\s\S]*?<\/script>/gi,"");
h=h.replace(/<style[\s\S]*?<\/style>/gi,"");
h=h.replace(/<svg[\s\S]*?<\/svg>/gi,"");
h=h.replace(/<nav[\s\S]*?<\/nav>/gi,"");
h=h.replace(/<footer[\s\S]*?<\/footer>/gi,"");
h=h.replace(/<!--[\s\S]*?-->/g,"");
function decode(s){return s
  .replace(/&amp;/g,"&").replace(/&lt;/g,"<").replace(/&gt;/g,">")
  .replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/&rsquo;/g,"’")
  .replace(/&lsquo;/g,"‘").replace(/&rdquo;/g,"”").replace(/&ldquo;/g,"“")
  .replace(/&ndash;/g,"–").replace(/&mdash;/g,"—").replace(/&reg;/g,"®")
  .replace(/&nbsp;/g," ").replace(/&trade;/g,"™").replace(/&#x27;/g,"'")
  .replace(/&hellip;/g,"…").replace(/&#\d+;/g,"");}
const tags=["h1","h2","h3","h4","p","li","blockquote"];
for(const tag of tags){
  const re=new RegExp("<"+tag+"[^>]*>([\\s\\S]*?)<\\/"+tag+">","gi");
  let m;
  while((m=re.exec(h))){
    let txt=m[1].replace(/<[^>]+>/g," ");
    txt=decode(txt).replace(/\s+/g," ").trim();
    if(txt && txt.length>1) console.log(tag.toUpperCase()+" | "+txt);
  }
}
EOF
node extract.js home.html 2>/dev/null | head -120

